/**
 * `gen-fixtures --out <dir>`: writes the deterministic resource fixtures produced by
 * @mu-reengineer/formats/testing and re-parses every one of them. This is the end-to-end smoke test
 * used by CI: it proves the readers against files that went through the disk.
 *
 * The fixtures are generated by our own code and contain no game content.
 */

import path from 'node:path';

import {
  buildAttFixture,
  buildBmdFixture,
  buildDdsFixture,
  buildMapFixture,
  buildObjFixture,
  buildOzbFixture,
  buildOzjFixture,
  buildOztFixture,
  buildTgaFixture,
  decodeDds,
  decodeOzb,
  decodeOzt,
  decodeTga,
  inspectOzj,
  parseAtt,
  parseBmd,
  parseMap,
  parseObj,
  summarizeBmd,
} from '@mu-reengineer/formats';

import { formatBytes, writeBytes } from '../fs-utils.js';

export interface FixtureRow {
  file: string;
  writer: string;
  reader: string;
  bytes: number;
  ok: boolean;
  detail: string;
}

export interface FixtureResult {
  outDir: string;
  rows: FixtureRow[];
  ok: boolean;
}

function check(name: string, writer: string, reader: string, bytes: number, run: () => string): FixtureRow {
  try {
    return { file: name, writer, reader, bytes, ok: true, detail: run() };
  } catch (error) {
    return { file: name, writer, reader, bytes, ok: false, detail: (error as Error).message };
  }
}

export async function generateFixtures(outDir: string): Promise<FixtureResult> {
  const rows: FixtureRow[] = [];
  const write = async (name: string, data: Uint8Array): Promise<number> => {
    await writeBytes(path.join(outDir, name), data);
    return data.length;
  };

  // --- BMD ------------------------------------------------------------------------------------
  const bmd12 = buildBmdFixture({ version: 12 });
  const bmd12Bytes = await write('model_v12.bmd', bmd12.bytes);
  rows.push(
    check('model_v12.bmd', 'buildBmdFixture(v12)', 'parseBmd', bmd12Bytes, () => {
      const model = parseBmd(bmd12.bytes);
      const summary = summarizeBmd(model);
      return `v${model.version} "${model.name}" meshes=${summary.meshes} tris=${summary.triangles} bones=${model.bones.length}`;
    }),
  );

  const bmd15 = buildBmdFixture({ version: 15, name: 'lea-model' });
  const bmd15Bytes = await write('model_v15.bmd', bmd15.bytes);
  rows.push(
    check('model_v15.bmd', 'buildBmdFixture(v15)', 'parseBmd (LEA-256)', bmd15Bytes, () => {
      const model = parseBmd(bmd15.bytes);
      return `v${model.version} "${model.name}" meshes=${model.meshes.length} payload=${model.encryptedPayloadSize}`;
    }),
  );

  // --- textures --------------------------------------------------------------------------------
  const ozt = buildOztFixture(8, 4);
  await write('diffuse.ozt', ozt.bytes);
  rows.push(
    check('diffuse.ozt', 'buildOztFixture(8,4)', 'decodeOzt', ozt.bytes.length, () => {
      const image = decodeOzt(ozt.bytes);
      return `${image.width}x${image.height} RGBA=${image.rgba.length}B`;
    }),
  );

  const ozb = buildOzbFixture(6, 3);
  await write('palette.ozb', ozb.bytes);
  rows.push(
    check('palette.ozb', 'buildOzbFixture(6,3)', 'decodeOzb', ozb.bytes.length, () => {
      const image = decodeOzb(ozb.bytes);
      return `${image.width}x${image.height} RGBA=${image.rgba.length}B`;
    }),
  );

  const ozj = buildOzjFixture(new Uint8Array([0xff, 0xd8, 0xff, 0xdb, 1, 2, 3, 4, 0xff, 0xd9]));
  await write('photo.ozj', ozj.bytes);
  rows.push(
    check('photo.ozj', 'buildOzjFixture(jpeg)', 'inspectOzj', ozj.bytes.length, () => {
      const info = inspectOzj(ozj.bytes);
      return `jpeg at ${info.jpegOffset}, ${info.jpeg.length}B, topDown=${info.topDownSort}`;
    }),
  );

  const tga = buildTgaFixture(4, 4, true);
  await write('rle.tga', tga.bytes);
  rows.push(
    check('rle.tga', 'buildTgaFixture(4,4,rle)', 'decodeTga', tga.bytes.length, () => {
      const image = decodeTga(tga.bytes);
      return `${image.width}x${image.height} RGBA=${image.rgba.length}B`;
    }),
  );

  const dds = buildDdsFixture();
  await write('dxt1.dds', dds.bytes);
  rows.push(
    check('dxt1.dds', 'buildDdsFixture()', 'decodeDds', dds.bytes.length, () => {
      const image = decodeDds(dds.bytes);
      return `${image.width}x${image.height} RGBA=${image.rgba.length}B`;
    }),
  );

  // --- terrain ---------------------------------------------------------------------------------
  const att = buildAttFixture({ extended: true });
  await write('world1.att', att.bytes);
  rows.push(
    check('world1.att', 'buildAttFixture(extended)', 'parseAtt', att.bytes.length, () => {
      const parsed = parseAtt(att.bytes);
      return `${parsed.width}x${parsed.height} extended=${parsed.isExtended} cipher=${parsed.cipher}`;
    }),
  );

  const map = buildMapFixture();
  await write('world1.map', map.bytes);
  rows.push(
    check('world1.map', 'buildMapFixture()', 'parseMap', map.bytes.length, () => {
      const parsed = parseMap(map.bytes);
      return `map #${parsed.mapNumber}, layer1=${parsed.layer1.length} layer2=${parsed.layer2.length} alpha=${parsed.alpha.length}`;
    }),
  );

  const obj = buildObjFixture();
  await write('world1.obj', obj.bytes);
  rows.push(
    check('world1.obj', 'buildObjFixture()', 'parseObj', obj.bytes.length, () => {
      const parsed = parseObj(obj.bytes);
      return `map #${parsed.mapNumber}, ${parsed.objects.length} objects, version ${parsed.version}`;
    }),
  );

  const total = rows.reduce((sum, row) => sum + row.bytes, 0);
  const report = {
    generated: new Date().toISOString(),
    outDir,
    totalBytes: total,
    ok: rows.every((row) => row.ok),
    rows,
  };
  await writeBytes(path.join(outDir, 'fixtures-report.json'), new TextEncoder().encode(`${JSON.stringify(report, null, 2)}\n`));

  return { outDir, rows, ok: report.ok };
}

export function formatFixtures(result: FixtureResult): string[] {
  const lines: string[] = [`fixtures written to ${result.outDir}`];
  for (const row of result.rows) {
    lines.push(`  ${row.ok ? 'ok  ' : 'FAIL'} ${row.file.padEnd(16)} ${formatBytes(row.bytes).padStart(9)}  ${row.reader.padEnd(22)} ${row.detail}`);
  }
  lines.push(`  ${result.rows.filter((row) => row.ok).length}/${result.rows.length} fixtures re-parsed successfully`);
  return lines;
}
